/* ------------------------------------------------------------------ */
/* 通用工具                                                            */
/* ------------------------------------------------------------------ */
export const clamp = (v, a, b) => (v < a ? a : (v > b ? b : v))
const _f32 = new Float32Array(1), _u32 = new Uint32Array(_f32.buffer)
/* 复刻 GLSL mediump(f16)：十位尾数、就近取偶 */
export function medium(v) { _f32[0] = v; let b = _u32[0]; b = ((b + 0xfff + ((b >>> 13) & 1)) & ~0x1fff) >>> 0; _u32[0] = b; return _f32[0] }
/* 与 Rust noise_index 相同：镜像（mirror）寻址 */
export function noiseIndex(v, size) { v = v % 2; if (v < 0) v += 2; if (v > 1) v = 2 - v; const i = Math.floor(v * size); return i < 0 ? 0 : (i > size - 1 ? size - 1 : i) }

export const CENTERED = (() => { const t = new Float32Array(256); for (let i = 0; i < 256; i++) t[i] = medium(medium(i / 255) - 0.5); return t })()
export const GLOW_W = (() => {
  let s = 0; for (let k = 1; k <= 6; k++) s += Math.pow(k, 2.65)
  return Array.from({ length: 6 }, (_, p) => Math.pow(6 - p, 2.65) / s)
})()
